enum QuoteTargetType {
  venue('venue'),
  provider('provider'),
  unknown('unknown');

  const QuoteTargetType(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static QuoteTargetType fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return QuoteTargetType.unknown;
  }

  String toJson() => value;
}

