enum RegionMatchKind {
  governorate('governorate'),
  area('area'),
  venue('venue'),
  unknown('unknown');

  const RegionMatchKind(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static RegionMatchKind fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return RegionMatchKind.unknown;
  }

  String toJson() => value;
}
